import { describe, it, expect } from 'vitest';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

/**
 * The project map must describe the tree that actually exists.
 *
 * `docs/blueprint/INVENTORY.md` is generated by `scripts/project-map.mjs` from
 * the working tree. This test compares the committed file with a fresh build,
 * so a new page, component, edge function, migration or test cannot land while
 * the map still describes yesterday's repo. The generator has its own minimum
 * counts per group — a broken glob fails there instead of producing a clean but
 * empty map.
 *
 * Fix when red: `npm run docs:map`, review the diff, commit it with the change.
 */
const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const INVENTORY = path.join(ROOT, 'docs', 'blueprint', 'INVENTORY.md');

describe('project map', () => {
  it('covers every structural surface', async () => {
    const { buildProjectMap } = await import('../../scripts/project-map.mjs');
    const content = buildProjectMap();

    // Anti-vacuity: the sections must exist even if a future refactor renames
    // groups. The counts themselves are enforced inside the generator.
    for (const heading of [
      '## Pages (',
      '## Components (',
      '## Edge functions (',
      '## Database migrations (',
      '## Test suite (',
      '## CI / deploy workflows (',
    ]) {
      expect(content).toContain(heading);
    }
    expect(content).toContain('Total tracked structure:');
  });

  it('matches the committed inventory byte for byte', async () => {
    const { buildProjectMap } = await import('../../scripts/project-map.mjs');
    const expected = buildProjectMap();
    const actual = fs.readFileSync(INVENTORY, 'utf8');

    expect(
      actual,
      'docs/blueprint/INVENTORY.md is stale. Run `npm run docs:map`, review the diff, and commit it with your change.'
    ).toBe(expected);
  });
});
